  const lib = new PhotoLibrary({ tree, grants, now, ...(o.template ? { template: o.template } : {}), ...(o.trashDays !== undefined ? { trashDays: o.trashDays } : {}), groupsOf: (p) => o.groups?.[p] ?? [] });
